367	<script>
368	(function () {
369	  // The minimal animation stylesheet each asset depends on. Embedded inside the
370	  // copied <svg> so the asset stays self-animating when dropped into any project.
371	  var ANIM_CSS = [
372	    '@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}',
373	    '@keyframes blink{0%,92%,100%{transform:scaleY(1)}96%{transform:scaleY(.1)}}',
374	    '@keyframes sway{0%,100%{transform:rotate(-4deg)}50%{transform:rotate(4deg)}}',
375	    '@keyframes pop{0%{transform:scale(0);opacity:0}60%{transform:scale(1.15);opacity:1}100%{transform:scale(1)}}',
376	    '@keyframes draw{to{stroke-dashoffset:0}}',
377	    '@keyframes confetti{0%{transform:translateY(0) rotate(0);opacity:1}100%{transform:translateY(-46px) rotate(220deg);opacity:0}}',
378	    '@keyframes spin{to{transform:rotate(360deg)}}',
379	    '@keyframes pulse{0%,100%{transform:scale(1);opacity:.9}50%{transform:scale(1.12);opacity:.5}}',
380	    '@keyframes wiggle{0%,100%{transform:rotate(0)}25%{transform:rotate(8deg)}75%{transform:rotate(-8deg)}}',
381	    '@keyframes orbit{to{transform:rotate(-360deg)}}',
382	    '@keyframes rise{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}',
383	    '@keyframes twinkle{0%,100%{opacity:.2;transform:scale(.6)}50%{opacity:1;transform:scale(1)}}',
384	    '@keyframes heartbeat{0%,100%{transform:scale(1)}15%{transform:scale(1.13)}30%{transform:scale(1)}45%{transform:scale(1.08)}}',
385	    '.a-float{animation:float 4s ease-in-out infinite;transform-origin:center}',
386	    '.a-blink{animation:blink 5s ease-in-out infinite;transform-origin:center}',
387	    '.a-sway{animation:sway 4.5s ease-in-out infinite;transform-origin:50% 90%}',
388	    '.a-pop{animation:pop .7s cubic-bezier(.2,1.3,.4,1) both}',
389	    '.a-spin{animation:spin 1.4s linear infinite;transform-origin:center}',
390	    '.a-pulse{animation:pulse 2.6s ease-in-out infinite;transform-origin:center}',
391	    '.a-wiggle{animation:wiggle 3.5s ease-in-out infinite;transform-origin:50% 80%}',
392	    '.a-orbit{animation:orbit 6s linear infinite;transform-origin:center}',
393	    '.a-rise{animation:rise 3s ease-in-out infinite;transform-origin:center}',
394	    '.a-twinkle{animation:twinkle 2s ease-in-out infinite;transform-origin:center}',
395	    '.a-heartbeat{animation:heartbeat 2.4s ease-in-out infinite;transform-origin:center}',
396	    '.draw{stroke-dasharray:90;stroke-dashoffset:90;animation:draw 1s ease-out .25s forwards}',
397	    '.conf{animation:confetti 1.3s ease-out infinite}',
398	    '.conf:nth-child(odd){animation-duration:1.6s}',
399	    '@media (prefers-reduced-motion:reduce){.a-float,.a-blink,.a-sway,.a-pop,.a-spin,.a-pulse,.a-wiggle,.a-orbit,.a-rise,.a-twinkle,.a-heartbeat,.conf{animation:none}.draw{stroke-dashoffset:0}}'
400	  ].join('');
401	
402	  // Build standalone, self-animating SVG markup for one card's stage <svg>.
403	  function buildSvg(svg) {
404	    var clone = svg.cloneNode(true);
405	    var style = document.createElementNS('http://www.w3.org/2000/svg', 'style');
406	    style.textContent = ANIM_CSS;
407	    clone.insertBefore(style, clone.firstChild);
408	    if (!clone.getAttribute('xmlns')) clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
409	    return clone.outerHTML.replace(/></g, '>\n<');
410	  }
411	
412	  var toast = document.getElementById('toast'), toastTimer;
413	  function showToast(msg) {
414	    toast.textContent = msg;
415	    toast.classList.add('show');
416	    clearTimeout(toastTimer);
417	    toastTimer = setTimeout(function () { toast.classList.remove('show'); }, 1800);
418	  }
419	
420	  var COPY_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg>';
421	  var DONE_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 13l4 4L19 7"/></svg>';
422	
423	  function fallbackCopy(text) {
424	    var ta = document.createElement('textarea');
425	    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
426	    document.body.appendChild(ta); ta.select();
427	    var ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
428	    document.body.removeChild(ta); return ok;
429	  }
430	
431	  document.querySelectorAll('.card').forEach(function (card) {
432	    var svg = card.querySelector('.stage svg');
433	    if (!svg) return;
434	    var name = (card.querySelector('.name') || {}).textContent || 'asset';
435	    var btn = document.createElement('button');
436	    btn.type = 'button';
437	    btn.className = 'copy-btn';
438	    btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
439	    btn.setAttribute('aria-label', 'Copy SVG markup for ' + name);
440	
441	    btn.addEventListener('click', function () {
442	      var markup = buildSvg(svg);
443	      var done = function () {
444	        btn.classList.add('done');
445	        btn.innerHTML = DONE_IC + '<span>Copied!</span>';
446	        showToast('SVG copied — paste it anywhere');
447	        setTimeout(function () {
448	          btn.classList.remove('done');
449	          btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
450	        }, 1800);
451	      };
452	      if (navigator.clipboard && navigator.clipboard.writeText) {
453	        navigator.clipboard.writeText(markup).then(done, function () {
454	          if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
455	        });
456	      } else {
457	        if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
458	      }
459	    });
460	
461	    card.querySelector('.body').appendChild(btn);
462	  });
463	})();
464	</script>
